import json
import pandas as pd
import numpy as np
import pdfplumber
from pathlib import Path

pdf_path = Path('/root/employees_backup.pdf')
xlsx_path = Path('/root/employees_current.xlsx')

# Extract PDF tables
rows = []
columns = None
with pdfplumber.open(pdf_path) as pdf:
    for page in pdf.pages:
        tables = page.extract_tables()
        for table in tables:
            if not table:
                continue
            if columns is None:
                header = table[0]
                if header and 'ID' in header:
                    columns = header
                    data_rows = table[1:]
                else:
                    columns = ['ID','First','Last','Dept','Position','Salary','Years','Location','Score']
                    data_rows = table
            else:
                if table[0] and 'ID' in table[0]:
                    data_rows = table[1:]
                else:
                    data_rows = table
            for row in data_rows:
                if row is None:
                    continue
                if all((c is None or str(c).strip()=='' ) for c in row):
                    continue
                rows.append(row)

if columns is None:
    raise SystemExit('No header detected in PDF')

clean_rows = []
for r in rows:
    if len(r) < len(columns):
        r = r + [None]*(len(columns)-len(r))
    if len(r) > len(columns):
        r = r[:len(columns)]
    clean_rows.append(r)

pdf_df = pd.DataFrame(clean_rows, columns=columns)

# clean strings
for col in pdf_df.columns:
    pdf_df[col] = pdf_df[col].apply(lambda x: x.strip() if isinstance(x,str) else x)

# convert numeric fields
pdf_df['Salary'] = pd.to_numeric(pdf_df['Salary'].astype(str).str.replace(',','', regex=False), errors='coerce')
pdf_df['Years'] = pd.to_numeric(pdf_df['Years'], errors='coerce')
pdf_df['Score'] = pd.to_numeric(pdf_df['Score'], errors='coerce')
pdf_df['ID'] = pdf_df['ID'].astype(str)

# Read current Excel
cur_df = pd.read_excel(xlsx_path, sheet_name=0, dtype={'ID': str})

# Strip whitespace in text columns
for col in cur_df.columns:
    if cur_df[col].dtype == object:
        cur_df[col] = cur_df[col].apply(lambda x: x.strip() if isinstance(x, str) else x)

# Ensure numeric columns are numeric
for col in ['Salary','Years','Score']:
    if col in cur_df.columns:
        cur_df[col] = pd.to_numeric(cur_df[col], errors='coerce')

# Index by ID
pdf_df = pdf_df.set_index('ID', drop=False)
cur_df = cur_df.set_index('ID', drop=False)

pdf_ids = set(pdf_df.index)
cur_ids = set(cur_df.index)

# Deleted employees
deleted_ids = sorted(pdf_ids - cur_ids)

# Modified employees
modified = []

# columns to compare (excluding ID)
compare_cols = [c for c in pdf_df.columns if c != 'ID' and c in cur_df.columns]

for emp_id in sorted(pdf_ids & cur_ids):
    old_row = pdf_df.loc[emp_id]
    new_row = cur_df.loc[emp_id]
    for col in compare_cols:
        old_val = old_row[col]
        new_val = new_row[col]
        # handle NaN
        if pd.isna(old_val) and pd.isna(new_val):
            continue
        # numeric comparison
        if col in ['Salary','Years']:
            # compare as int if possible
            if pd.isna(old_val) or pd.isna(new_val):
                changed = True
            else:
                changed = int(old_val) != int(new_val)
            if changed:
                modified.append({
                    'id': emp_id,
                    'field': col,
                    'old_value': None if pd.isna(old_val) else int(old_val),
                    'new_value': None if pd.isna(new_val) else int(new_val)
                })
            continue
        if col == 'Score':
            if pd.isna(old_val) or pd.isna(new_val):
                changed = True
            else:
                changed = not np.isclose(float(old_val), float(new_val), rtol=0, atol=1e-9)
            if changed:
                modified.append({
                    'id': emp_id,
                    'field': col,
                    'old_value': None if pd.isna(old_val) else float(old_val),
                    'new_value': None if pd.isna(new_val) else float(new_val)
                })
            continue
        # text fields
        if old_val != new_val:
            modified.append({
                'id': emp_id,
                'field': col,
                'old_value': old_val if not pd.isna(old_val) else None,
                'new_value': new_val if not pd.isna(new_val) else None
            })

# sort modified by id then field
modified.sort(key=lambda x: (x['id'], x['field']))

report = {
    'deleted_employees': deleted_ids,
    'modified_employees': modified
}

out_path = Path('/root/diff_report.json')
with open(out_path, 'w', encoding='utf-8') as f:
    json.dump(report, f, ensure_ascii=False, indent=2)

print('deleted', len(deleted_ids))
print('modified', len(modified))
print('output', out_path)
